-- UrbanLink Flow: dados de demonstração.
--
-- Rode depois do 02, dentro do banco:
--   psql -U postgres -d urbanlink -f 03-inserir-dados.sql
--
-- São os mesmos dados do "npm run db:seed" do back-end: 3 usuários, 2 centros de distribuição,
-- 8 veículos, 24 entregas com o histórico de cada uma, 3 rotas, 2 simulações e 3 alertas.
-- As datas são relativas à hora em que o script roda (now() + intervalo), pra demonstração ficar
-- sempre atual.
--
-- Usuários (todos com a senha UrbanLink@2026, só pra uso local):
--   admin@urbanlink.local (ADMIN), manager@urbanlink.local (MANAGER), operator@urbanlink.local (OPERATOR)
-- Códigos de rastreio: ULF-2026-0001 a ULF-2026-0024.
--
-- Gerado em 2026-11-20 a partir de um banco com o seed.

BEGIN;

-- O histórico das entregas vem pronto logo abaixo; o trigger fica desligado enquanto elas entram,
-- pra não gravar um evento a mais por entrega.
ALTER TABLE "deliveries" DISABLE TRIGGER "deliveries_record_event";

-- users (3)

-- distribution_centers (2)

-- vehicles (8)

-- deliveries (24)

-- delivery_events (65)

-- routes (3)

-- route_stops (16)

-- simulations (2)

-- simulation_results (2)

-- alerts (3)

-- audit_logs (3)

ALTER TABLE "deliveries" ENABLE TRIGGER "deliveries_record_event";

-- O próximo evento do histórico continua a numeração.
SELECT setval(pg_get_serial_sequence('"delivery_events"', 'id'), COALESCE((SELECT max("id") FROM "delivery_events"), 0) + 1, false);

COMMIT;
